// DOMPurify fallback placeholder - official library is downloaded during GitHub Actions build
(function (global) {
    if (typeof global.DOMPurify === 'undefined') {
        global.DOMPurify = {
            sanitize: function (dirtyHtml) {
                if (!dirtyHtml) return "";
                return String(dirtyHtml)
                    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
                    .replace(/on\w+="[^"]*"/gi, '')
                    .replace(/on\w+='[^']*'/gi, '')
                    .replace(/javascript:[^"']*/gi, '#');
            }
        };
    }
})(typeof window !== 'undefined' ? window : this);
